afterExample:
package test;

import org.eclipse.jface.dialogs.Dialog;
import org.eclipse.swt.widgets.Shell;

public class MyQuickSearchDialog extends Dialog {

    protected MyQuickSearchDialog(Shell parentShell) {
        super(parentShell);
    }

    public void setup() {
        this.setTitle("Quick Search"); // This is the expected change
        System.out.println("Other text search");
    }
}

